	ARDA_DEFINE_GRAPH_NODE(FArdaPixelSortSortNode, PixelSortSort);

	struct FArdaPixelSortSortNode::FArdaState
	{
		FArdaRHIDeviceRef mDevice;
		eastl::shared_ptr<const FArdaNativeComputeRegistry> mRegistry;

		FArdaRHIStatus Initialize()
		{
			auto Registry = GetPixelSortRegistry();
			mRegistry = eastl::move(Registry.mValue);
			return eastl::move(Registry.mStatus);
		}
	};

	FArdaRHIStatus FArdaPixelSortSortNode::DeclareResources(FArdaDependencyResourceContext& C, FArdaParameters& P)
	{
		FArdaRHITextureDesc D;
		D.mWidth = P.mWidth;
		D.mHeight = P.mHeight;
		D.mFormat = EArdaRHIFormat::RGBA8UInt;
		D.mbCudaInterop = bool(CheckPixelSortNativeSupport(C.GetDevice()));
		D.mUsage = EArdaRHITextureUsage::UnorderedAccess | EArdaRHITextureUsage::ShaderResource;
		return C.Texture(P.mSorted, "Output", D);
	}

	bool FArdaPixelSortSortNode::UsesComputeAlternative(const IArdaRHIDevice* Device)
	{
		return Device && CheckPixelSortNativeSupport(Device).mCode == EArdaRHIResult::Unsupported;
	}

	FArdaDependencyNodeMetadata FArdaPixelSortSortNode::GetMetadata()
	{
		return {"example.pixel-sort.radix", 1};
	}

	eastl::string FArdaPixelSortSortNode::GetCanonicalKey(const FArdaParameters& P)
	{
		return FArdaDependencyKeyBuilder()
		    .Resource(P.mNoise)
		    .Resource(P.mSorted)
		    .Value(reinterpret_cast<uintptr_t>(P.mInput.get()))
		    .Value(P.mWidth)
		    .Value(P.mHeight)
		    .Build();
	}

	FArdaRHIStatus FArdaPixelSortSortNode::Validate(const FArdaParameters& P)
	{
		if (!P.mInput)
		{
			return FArdaRHIStatus::Error(EArdaRHIResult::InvalidArgument,
			    "PixelSort sorting requires dynamic sort inputs.");
		}
		return ValidatePixelSortExtent(P.mWidth, P.mHeight);
	}

	TArdaRHIResult<eastl::shared_ptr<const FArdaPixelSortSortNode::FArdaState>> FArdaPixelSortSortNode::Prepare(
	    FArdaRHIDeviceRef Device)
	{
		return PrepareExampleNodeState<FArdaState>(eastl::move(Device));
	}

	namespace
	{
		TArdaRHIResult<FArdaNativeInvocation> MakeNodeInvocation(FArdaDependencyExecutionContext& C,
		    const FArdaPixelSortSortParameters& P)
		{
			FArdaPixelSortParameters Host;
			if (auto Status = ResolveNodeCudaParameters(C, P, Host); !Status)
			{
				return {{}, eastl::move(Status)};
			}
			Host.mWidth = P.mWidth;
			Host.mHeight = P.mHeight;
			Host.mChannel = P.mInput->mChannel;
			Host.mThreshold = P.mInput->mThreshold;
			return MakePixelSortInvocation(Host);
		}
	}

	FArdaRHIStatus FArdaPixelSortSortNode::PrepareCuda(FArdaDependencyExecutionContext& C,
	    const FArdaParameters& P,
	    const FArdaState& Prepared,
	    FArdaInstanceState&,
	    FArdaCudaSequence& Sequence)
	{
		auto Invocation = MakeNodeInvocation(C, P);
		return Invocation ? C.AppendNativeCudaCompute(Sequence, *Prepared.mRegistry, ArdaPixelSortOperandId, Invocation.mValue)
		                  : Invocation.mStatus;
	}

	FArdaRHIStatus FArdaPixelSortSortNode::RecordComputeAlternative(FArdaDependencyExecutionContext& C,
	    const FArdaParameters& P,
	    const FArdaState& Prepared,
	    FArdaInstanceState&)
	{
		auto Invocation = MakeNodeInvocation(C, P);
		return Invocation ? C.RecordNativeCompute(*Prepared.mRegistry,
		                        ArdaPixelSortOperandId,
		                        Invocation.mValue,
		                        EArdaNativeComputePreference::ShaderOnly)
		                  : Invocation.mStatus;
	}
